const D = { energy:.6, scale:1, density:.5, speed:1, hue:28, x:.5, y:.92, reach:.62, anno:.6, style:'film', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const lp = (a,b,s) => a+(b-a)*s;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);

function pal(){
  if (sty==='cyanotype') return { line:[200,6,99], body:[208,52,40], dark:[214,70,16], ctr:[196,38,80], anno:[200,12,92], hatch:[204,44,58], hot:[46,70,98], joint:[196,24,90], add:false };
  if (sty==='engraving') return { line:[28,40,10], body:[36,14,66], dark:[32,26,34], ctr:[8,64,42], anno:[28,42,14], hatch:[30,30,26], hot:[6,74,44], joint:[28,34,20], add:false };
  if (sty==='ghost')     return { line:[H,26,98], body:[H,62,30], dark:[H,66,12], ctr:[12,72,60], anno:[H,16,86], hatch:[H,44,52], hot:[46,74,100], joint:[H,12,100], add:true };
  if (sty==='kinematic') return { line:[178,64,94], body:[190,50,22], dark:[196,44,10], ctr:[10,72,68], anno:[52,56,88], hatch:[186,42,44], hot:[340,74,96], joint:[178,30,96], add:false };
  return { line:[H,6,94], body:[H,18,42], dark:[H,26,16], ctr:[10,66,62], anno:[H,8,88], hatch:[H,12,58], hot:[H+14,72,96], joint:[H,10,88], add:false };
}
const C = pal();
const hw = q => ((q%360)+360)%360;
const sc = (c,a) => { stroke(hw(c[0]), c[1], c[2], a*AL); };
const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const kin = (sty==='kinematic');

// ---- program clock: monotonic, wandering -> the pose never re-phases ---------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const wob = 1 + .21*Math.sin(K.t*.127) + .13*Math.sin(K.t*.309+1.4) + .07*Math.sin(K.t*.741+2.7);
S.pg = (S.pg||0) + dt * P.speed * (.14 + .30*NRG) * wob * (.6+.7*K.intensity);
const drx = .9*Math.sin(K.t*.137) + .5*Math.sin(K.t*.293+1.7) + .32*Math.sin(K.t*.451);
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- rig ---------------------------------------------------------------------
const SCA = cl(P.scale,.4,2.0);
const HT = u*.50*SCA;                     // the arm stands ~half the frame at scale 1
const bx = cl(P.x,.08,.92)*width  + u*.008*NRG*drx;
const by = cl(P.y,.35,1.02)*height;
const h0 = HT*.30;                        // pedestal + column to the shoulder
const L1 = HT*.34, L2 = HT*.28, L3 = HT*.11;
const REACH = (L1+L2+L3) * cl(P.reach,.25,1);

// ---- pick-and-place programme (seeded waypoints in the reach annulus) --------
const NW = Math.round(4 + cl(P.density,0,1)*5);
if (S.wk !== sd+'|'+NW+'|'+Math.round(HT)){
  S.wk = sd+'|'+NW+'|'+Math.round(HT);
  S.wp = [];
  for (let i=0;i<NW;i++){
    const rr = lp(.42, .97, fr(i*3.7+2)) * REACH;
    const aa = lp(-.30, 1.55, fr(i*5.3+7));                 // polar angle in the working plane
    S.wp.push({ r: Math.cos(aa)*rr, y: h0 + Math.sin(aa)*rr*.9,
      yaw: lp(-.85, .85, fr(i*7.1+11)), wa: lp(-1.5, .5, fr(i*9.7+13)),
      grip: fr(i*11.3+17) < .5 ? 1 : 0, dwell: .18 + fr(i*13.7+19)*.30 });
  }
}
const WP = S.wp || [];
const ease = s => s*s*(3-2*s);
const seg = Math.floor(S.pg) % Math.max(1,WP.length);
const rawF = S.pg - Math.floor(S.pg);
const w0 = WP[seg] || {r:REACH*.5,y:h0,yaw:0,wa:0,grip:0,dwell:.2};
const w1 = WP[(seg+1)%Math.max(1,WP.length)] || w0;
const mf = cl((rawF - w0.dwell)/Math.max(.05, 1-w0.dwell), 0, 1);
const f = ease(mf);
const tr = lp(w0.r, w1.r, f), ty = lp(w0.y, w1.y, f);
const yaw = lp(w0.yaw, w1.yaw, f) + .09*Math.sin(K.t*.089) + .05*Math.sin(K.t*.211+1.3);
const wa = lp(w0.wa, w1.wa, f);
const holding = (mf < .5 ? w0.grip : w1.grip);
const gripO = lp(w0.grip?0:1, w1.grip?0:1, f);

// working plane (r, y) -> screen, with base yaw giving foreshortening + a light axonometric lift
const SXf = (r,y) => bx + r*Math.cos(yaw);
const SYf = (r,y) => by - y + r*Math.sin(yaw)*.22;
const PJ = (r,y) => [SXf(r,y), SYf(r,y)];

// ---- analytic 2-link IK to the wrist centre ---------------------------------
const wcr = tr - Math.cos(wa)*L3, wcy = ty - Math.sin(wa)*L3;
const sr = 0, sy = h0;
let dx2 = wcr - sr, dy2 = wcy - sy;
let dd = Math.hypot(dx2, dy2);
const dmin = Math.abs(L1-L2)+HT*.012, dmax = L1+L2-HT*.012;
if (dd < 1e-5){ dx2 = dmin; dd = dmin; }
if (dd < dmin || dd > dmax){ const k2 = cl(dd, dmin, dmax)/dd; dx2*=k2; dy2*=k2; dd = Math.hypot(dx2,dy2); }
const base = Math.atan2(dy2, dx2);
const cosB = cl((L1*L1 + dd*dd - L2*L2)/(2*L1*dd), -1, 1);
const th1 = base + Math.acos(cosB);                       // elbow-up
const er = sr + Math.cos(th1)*L1, ey2 = sy + Math.sin(th1)*L1;
const th2 = Math.atan2((sy+dy2) - ey2, (sr+dx2) - er);
const fr2 = sr + dx2, fy2 = sy + dy2;                     // wrist centre (reached)
const tcpR = fr2 + Math.cos(wa)*L3, tcpY = fy2 + Math.sin(wa)*L3;

// ---- TCP locus (a real trace of where the tool has been) --------------------
S.loc = S.loc || [];
S.loc.push(tcpR, tcpY, yaw);
if (S.loc.length > 3*260) S.loc.splice(0, S.loc.length - 3*260);

// ---- drawing helpers ---------------------------------------------------------
const LW = Math.max(1, u*.0026*(.6+.7*NRG))*cl(SCA,.6,1.6);
function ddot(x0,y0,x1,y1,per,a){
  const L=Math.hypot(x1-x0,y1-y0); if(L<.5) return;
  const ux=(x1-x0)/L, uy=(y1-y0)/L;
  sc(C.ctr, a); strokeWeight(Math.max(.4,u*.0008));
  for (let s=0;s<L;s+=per){
    line(x0+ux*s,y0+uy*s,x0+ux*Math.min(L,s+per*.58),y0+uy*Math.min(L,s+per*.58));
    const c=Math.min(L,s+per*.74); line(x0+ux*c,y0+uy*c,x0+ux*Math.min(L,c+per*.09),y0+uy*Math.min(L,c+per*.09));
  }
}
// a link drawn as a real machined member: tapered body, hatched section, hard outline
function link(r0,y0,r1,y1,w,tap){
  const a0=PJ(r0,y0), a1=PJ(r1,y1);
  const dx=a1[0]-a0[0], dy=a1[1]-a0[1], L=Math.hypot(dx,dy)||1;
  const nx=-dy/L*w, ny=dx/L*w, mx=-dy/L*w*tap, my=dx/L*w*tap;
  if (kin){ sc(C.line, 84); strokeWeight(Math.max(.8,LW*.6)); line(a0[0],a0[1],a1[0],a1[1]); return; }
  noStroke(); fc(C.body, C.add?26:88);
  beginShape(); vertex(a0[0]+nx,a0[1]+ny); vertex(a1[0]+mx,a1[1]+my); vertex(a1[0]-mx,a1[1]-my); vertex(a0[0]-nx,a0[1]-ny); endShape(CLOSE);
  sc(C.hatch, 40); strokeWeight(Math.max(.4,u*.0007));
  const nh = Math.max(3, Math.round(L/(u*.018)));
  for (let i=1;i<nh;i++){ const s=i/nh, px=a0[0]+dx*s, py=a0[1]+dy*s, ww=lp(w,w*tap,s);
    line(px + nx/w*ww*.85, py + ny/w*ww*.85, px - nx/w*ww*.85 + dx*.06, py - ny/w*ww*.85 + dy*.06); }
  noFill(); sc(C.line, C.add?58+26*glow:94); strokeWeight(LW);
  beginShape(); vertex(a0[0]+nx,a0[1]+ny); vertex(a1[0]+mx,a1[1]+my); vertex(a1[0]-mx,a1[1]-my); vertex(a0[0]-nx,a0[1]-ny); endShape(CLOSE);
}
function joint(r,y,rad,lbl){
  const p=PJ(r,y);
  if (kin){ noStroke(); fc(C.joint, 94); ellipse(p[0],p[1],rad*.9,rad*.9);
    sc(C.ctr, 70); strokeWeight(Math.max(.4,u*.0008)); line(p[0]-rad,p[1],p[0]+rad,p[1]); line(p[0],p[1]-rad,p[0],p[1]+rad); return; }
  noStroke(); fc(C.dark, C.add?24:92); ellipse(p[0],p[1],rad*2,rad*2);
  noFill(); sc(C.line, 96); strokeWeight(LW*.8); ellipse(p[0],p[1],rad*2,rad*2);
  sc(C.line, 62); strokeWeight(Math.max(.4,u*.0008)); ellipse(p[0],p[1],rad*.8,rad*.8);
  sc(C.ctr, 74); strokeWeight(Math.max(.4,u*.0008));
  line(p[0]-rad*1.35,p[1],p[0]+rad*1.35,p[1]); line(p[0],p[1]-rad*1.35,p[0],p[1]+rad*1.35);
}

if (C.add) blendMode(ADD);

// ---- work envelope (dashed setting-out arc) + the TCP locus ------------------
if (anno > .2){
  sc(C.ctr, 26+22*anno); strokeWeight(Math.max(.4,u*.0008)); noFill();
  for (let i=0;i<44;i++){ if (i%3===2) continue;
    const a0=lp(-.42,1.72,i/44), a1=lp(-.42,1.72,(i+.72)/44);
    const p0=PJ(Math.cos(a0)*REACH, h0+Math.sin(a0)*REACH*.9), p1=PJ(Math.cos(a1)*REACH, h0+Math.sin(a1)*REACH*.9);
    line(p0[0],p0[1],p1[0],p1[1]); }
}
if (S.loc.length > 6){
  noFill(); sc(C.hot, 30+26*anno); strokeWeight(Math.max(.6,u*.0012));
  beginShape();
  for (let i=0;i<S.loc.length;i+=3){
    const yv = S.loc[i+2];
    vertex(bx + S.loc[i]*Math.cos(yv), by - S.loc[i+1] + S.loc[i]*Math.sin(yv)*.22);
  }
  endShape();
}

// ---- pedestal + column -------------------------------------------------------
{
  const b0=PJ(0,0), b1=PJ(0,h0);
  if (!kin){
    const pw = HT*.085;
    noStroke(); fc(C.dark, C.add?22:92);
    beginShape(); vertex(b0[0]-pw*1.5,b0[1]); vertex(b0[0]-pw*.9,b0[1]-HT*.055); vertex(b0[0]+pw*.9,b0[1]-HT*.055); vertex(b0[0]+pw*1.5,b0[1]); endShape(CLOSE);
    noFill(); sc(C.line, 92); strokeWeight(LW);
    beginShape(); vertex(b0[0]-pw*1.5,b0[1]); vertex(b0[0]-pw*.9,b0[1]-HT*.055); vertex(b0[0]+pw*.9,b0[1]-HT*.055); vertex(b0[0]+pw*1.5,b0[1]); endShape(CLOSE);
    sc(C.hatch, 46); strokeWeight(Math.max(.4,u*.0007));
    for (let i=-4;i<=4;i++) line(b0[0]+i*pw*.34, b0[1], b0[0]+i*pw*.34 - pw*.3, b0[1]+HT*.036);
    line(b0[0]-pw*1.7, b0[1], b0[0]+pw*1.7, b0[1]);
    // the yawing column: a barrel whose ellipse foreshortens with the base rotation
    link(0,HT*.04, 0,h0, HT*.058, .78);
    noFill(); sc(C.line, 70); strokeWeight(Math.max(.4,u*.0009));
    ellipse(b1[0], b1[1], HT*.116*Math.abs(Math.cos(yaw))+HT*.03, HT*.030);
  } else { sc(C.line, 80); strokeWeight(Math.max(.8,LW*.6)); line(b0[0],b0[1],b1[0],b1[1]); }
  ddot(b0[0], b0[1]+HT*.05, b1[0], b1[1]-HT*.10, u*.016, 44+20*anno);
}

// ---- the arm -----------------------------------------------------------------
link(sr,sy, er,ey2, HT*.045, .82);                 // upper arm
link(er,ey2, fr2,fy2, HT*.036, .78);               // forearm
link(fr2,fy2, tcpR,tcpY, HT*.022, .9);             // wrist / tool flange
joint(sr,sy, HT*.042);
joint(er,ey2, HT*.034);
joint(fr2,fy2, HT*.024);

// ---- gripper + the blank it is carrying --------------------------------------
{
  const tp = PJ(tcpR, tcpY);
  const ga = Math.atan2(PJ(tcpR,tcpY)[1]-PJ(fr2,fy2)[1], PJ(tcpR,tcpY)[0]-PJ(fr2,fy2)[0]);
  const gw = HT*.030, op = lp(.35, 1.5, gripO);
  push(); translate(tp[0], tp[1]); rotate(ga);
  sc(C.line, 96); strokeWeight(LW*.85); noFill();
  for (const s2 of [-1,1]){
    line(0, s2*gw*.5, gw*.9, s2*gw*op);
    line(gw*.9, s2*gw*op, gw*1.7, s2*gw*op);
  }
  if (holding && gripO < .5 && !kin){
    const bs = gw*1.15;
    noStroke(); fc(C.body, C.add?30:94); rect(gw*.7, -bs, bs*1.7, bs*2);
    noFill(); sc(C.line, 96); strokeWeight(LW*.8); rect(gw*.7, -bs, bs*1.7, bs*2);
    sc(C.hatch, 50); strokeWeight(Math.max(.4,u*.0007));
    for (let i=0;i<7;i++) line(gw*.7, -bs+i*bs*.30, gw*.7+bs*1.7, -bs+i*bs*.30 - bs*.5);
  }
  pop();
  noStroke(); fc(C.hot, (76+22*glow)); ellipse(tp[0], tp[1], HT*.014, HT*.014);
}
blendMode(BLEND);

// ---- joint-angle callouts (live degrees) + TCP readout -----------------------
if (anno > .12){
  textFont('monospace'); noStroke(); textSize(Math.max(6, Math.min(u*.0125, HT*.030)));
  const deg = a => (((a*57.2958)%360+360)%360).toFixed(0);
  const lab = (r,y,s2,ox,oy) => { const p=PJ(r,y);
    sc(C.anno, 44+26*anno); strokeWeight(Math.max(.4,u*.0007));
    line(p[0],p[1], p[0]+ox, p[1]+oy); line(p[0]+ox, p[1]+oy, p[0]+ox+(ox<0?-u*.022:u*.022), p[1]+oy);
    noStroke(); fc(C.anno, 90); textAlign(ox<0?RIGHT:LEFT, BOTTOM);
    text(s2, p[0]+ox+(ox<0?-u*.026:u*.026), p[1]+oy-u*.003); };
  lab(0, h0*.5, 'A1 '+deg(yaw)+' deg', -u*.055, -u*.010);
  lab(sr, sy, 'A2 '+deg(th1), u*.050, -u*.045);
  lab(er, ey2, 'A3 '+deg(th2-th1), u*.048, -u*.038);
  lab(fr2, fy2, 'A5 '+deg(wa-th2), -u*.050, -u*.030);
  if (anno > .45){
    textAlign(LEFT, TOP); fc(C.anno, 76);
    const tp = PJ(tcpR, tcpY);
    const ts = Math.max(6, Math.min(u*.0115, HT*.028));
    textSize(ts);
    text('TCP X'+(tcpR/HT*1000).toFixed(0)+' Z'+(tcpY/HT*1000).toFixed(0), tp[0]+u*.020, tp[1]+u*.014);
    text(holding && gripO<.5 ? 'GRIP CLOSED - PART HELD' : 'GRIP OPEN', tp[0]+u*.020, tp[1]+u*.014+ts*1.4);
    text('PROG P'+(seg+1)+'/'+WP.length+(mf<=0?' DWELL':' MOVE'), tp[0]+u*.020, tp[1]+u*.014+ts*2.8);
  }
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
